{
  "nl": {
    "issue": [
      {
        "text": "合同内容一般包括哪些条款、能否参照示范文本；认购书、订购书、预订书等是否构成预约合同，违反预约合同订立义务的后果；格式条款如何认定，提供方负有何种义务，违反义务的后果",
        "rules": [
          "c470-2",
          "c495-1",
          "c495-2",
          "c496-1",
          "c496-2-notice",
          "c496-2-effect"
        ]
      }
    ],
    "conditions": [
      {
        "text": "合同内容由当事人约定，一般包括当事人姓名或名称和住所、标的、数量、质量、价款或报酬、履行期限地点和方式、违约责任、解决争议的方法（示范性列举，非强制）",
        "rules": []
      },
      {
        "text": "当事人约定在将来一定期限内订立合同的认购书、订购书、预订书等",
        "rules": [
          "c495-1"
        ]
      },
      {
        "text": "格式条款：当事人为了重复使用而预先拟定，并在订立合同时未与对方协商的条款",
        "rules": [
          "c496-1"
        ]
      },
      {
        "text": "提供格式条款一方未履行提示或者说明义务，致使对方没有注意或者理解与其有重大利害关系的条款",
        "rules": [
          "c496-2-effect"
        ]
      }
    ],
    "exceptions": [
      {
        "text": "提供格式条款一方已以合理方式提示对方注意、并按对方要求说明重大利害关系条款，使对方注意并理解的，对方不得主张该条款不成为合同内容",
        "rules": [
          "c496-2-effect"
        ]
      }
    ],
    "effects": [
      {
        "text": "当事人可以参照各类合同的示范文本订立合同",
        "rules": [
          "c470-2"
        ]
      },
      {
        "text": "约定将来一定期限内订立合同的认购书、订购书、预订书等构成预约合同",
        "rules": [
          "c495-1"
        ]
      },
      {
        "text": "预约合同成立后，订立本约合同是当事人应当履行的义务；本约未订立，预约合同即未履行（笔记）",
        "rules": [
          "c495-duty"
        ]
      },
      {
        "text": "一方不履行预约合同约定的订立合同义务的，对方可以请求其承担预约合同的违约责任",
        "rules": [
          "c495-2"
        ]
      },
      {
        "text": "提供格式条款一方应当遵循公平原则确定当事人之间的权利和义务，并采取合理方式提示对方注意免除或减轻其责任等重大利害关系条款，按对方要求予以说明",
        "rules": [
          "c496-2-fair",
          "c496-2-notice"
        ]
      },
      {
        "text": "未履行提示或说明义务致对方未注意或理解的，对方可以主张该条款不成为合同的内容",
        "rules": [
          "c496-2-effect",
          "c496-2-excl"
        ]
      }
    ],
    "priority": [
      {
        "text": "格式条款提供方未履行提示、说明义务的，相对人主张该条款不成为合同内容，构成对“合同内容由当事人约定”一般规则的例外",
        "rules": [
          "c496-2-excl"
        ]
      }
    ],
    "distinguish": [
      {
        "text": "预约合同与本约合同相对：本约合同是履行预约合同而订立的合同，预约的标的是将来订立本约（笔记）",
        "rules": [
          "c495-1",
          "c495-duty"
        ]
      },
      {
        "text": "格式条款与个别协商条款不同：须同时具备“为重复使用而预先拟定”与“订立合同时未与对方协商”两个特征",
        "rules": [
          "c496-1"
        ]
      },
      {
        "text": "第470条第1款为示范性列举，欠缺其中某项条款不当然影响合同成立，仅生内容解释与补充问题（学理）",
        "rules": []
      }
    ]
  },
